$.m_name = (e) => e.name;
$.m_value = (e) => e.value;

// ---- List / Set ----
$.m_clear = (c) => { if (Array.isArray(c)) c.length = 0; else if (c instanceof DsSet) c.items.length = 0; else c.clear(); };
