$.m_map = (c, f) => Array.from(c instanceof DsSet ? c.items : c).map((x) => f(x));

// ---- Map ----
$.m_has = (m, k) => m.has(k);
$.m_get = (m, k) => m.has(k) ? copy(m.get(k)) : null;
$.m_getOr = (m, k, fallback) => m.has(k) ? copy(m.get(k)) : fallback;
$.m_set = (m, k, v) => { m.set(k, v); };
$.m_keys = (m) => Array.from(m.keys());
$.m_values = (m) => Array.from(m.values()).map(copy);

$.zip = (a, b) => { const n = Math.min(a.length, b.length), out = []; for (let i = 0; i < n; i++) out.push([copy(a[i]), copy(b[i])]); return out; };
