        let rest = local - days * 86400000n;
        const z = Number(days) + 719468;
        const era = Math.floor(z / 146097), doe = z - era * 146097;
        const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
